            aOrbiterD = (((aWandererB + RotL64(aScatter, 37U)) + 0xE75D1FCC92517382ULL) + aSeedOrbiterAssignSaltC[(((31U - aIndex) + 11U)) & S_SALT1]) + aNonceWordA;
