            //
            aOrbiterC = ((aWandererD + RotL64(aScatter, 60U)) + RotL64(aCarry, 39U)) + 0x7A5EF9544098EC6AULL;
            aOrbiterE = (((aWandererF + RotL64(aIngress, 29U)) + 0xC78715543027E19FULL) + aSeedOrbiterAssignSaltF[(((31U - aIndex) + 19U)) & S_SALT1]) + aNonceWordB;
            aOrbiterH = ((aWandererI + RotL64(aCross, 41U)) + 0xB150FD34C0F14FA1ULL) + aNonceWordJ;
            aOrbiterG = (((aWandererG + RotL64(aPrevious, 47U)) + RotL64(aCarry, 3U)) + 0xA3DD4A348EA20202ULL) + aSeedOrbiterAssignSaltB[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterK = ((aWandererA + RotL64(aIngress, 19U)) + RotL64(aCarry, 23U)) + 0xD0F0C27A23D92B14ULL;
            aOrbiterF = (aWandererJ + RotL64(aCross, 53U)) + 0x9146A2772F13F0F7ULL;
