    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseA(pNonce * 0xF475B0336CF214C1ULL + 0xD297D10FEC5AE312ULL);
