            aOrbiterC = ((aWandererD + RotL64(aPrevious, 43U)) + 0xC7CD88C835B72696ULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterG = (aWandererG + RotL64(aScatter, 47U)) + 0x3AB28C6B8BF8F376ULL;
            aOrbiterF = ((aWandererE + RotL64(aCross, 39U)) + RotL64(aCarry, 3U)) + 0x29F4559F559EEB36ULL;
            aOrbiterB = ((aWandererI + RotL64(aIngress, 13U)) + 0x9DCD533DF1C14A66ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterD = (aWandererB + RotL64(aPrevious, 6U)) + 0xB54C08CFA06414F0ULL;
