            aOrbiterB = RotL64((aOrbiterB * 0x25889A1ABA7BE07FULL), 11U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterB) + 0x89BD06C9EF3BB68EULL) + aTwistOrbiterUpdateSaltF[((aIndex + 19U)) & S_SALT1];
