            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0xB023A8B0E34E1196ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0x8086F5FBAA0DEBBAULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 10U)) & S_SALT1];
