            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0xB70E66B52ADA1275ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0x862DBC7CD9F2CBB1ULL;
