            //
            aOrbiterC = (aWandererG + RotL64(aIngress, 35U)) + 0x4090C6A92C28615AULL;
            aOrbiterI = ((aWandererF + RotL64(aPrevious, 47U)) + 0x117B8361F8414E13ULL) + aTwistOrbiterAssignSaltA[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterH = (aWandererE + RotL64(aScatter, 5U)) + 0xC1ACE45AC335D4F2ULL;
            aOrbiterB = ((aWandererK + RotL64(aCross, 58U)) + RotL64(aCarry, 35U)) + 0x302531212A0C290CULL;
            aOrbiterG = (aWandererJ + RotL64(aScatter, 29U)) + 0x998DE1DC09A8184AULL;
            aOrbiterD = ((aWandererA + RotL64(aIngress, 11U)) + RotL64(aCarry, 3U)) + 0xE89CD057AE64C919ULL;
            aOrbiterF = (((aWandererD + RotL64(aPrevious, 41U)) + RotL64(aCarry, 51U)) + 0xB92B11032B139F97ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 11U)) & S_SALT1];
            //
            aOrbiterC = (aOrbiterC + aOrbiterI) + 0x8A0E7C3DFD7CE4ABULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0x42279E99A248BC96ULL) ^ aTwistOrbiterUpdateSaltA[((aIndex + 13U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x8857587B4502E963ULL), 29U);
            //
