            aOrbiterD = RotL64((aOrbiterD * 0x47DD7A7EE9D1EAA1ULL), 29U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterE) + 0x1BBE536C265026EBULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0x964DF16AE6B6AB16ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x081B9B4FAC208D55ULL), 13U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterF) + 0xBC77037BD72662DBULL;
