            //
            aWandererC = aWandererC + (((RotL64(aIngress, 26U) + RotL64(aOrbiterI, 53U)) + aOrbiterG) + RotL64(aCarry, 43U));
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 53U) + aOrbiterC) + RotL64(aOrbiterH, 39U));
