            aWandererK = aWandererK ^ (((RotL64(aCross, 47U) + aOrbiterE) + RotL64(aOrbiterB, 47U)) + aKeyRotateAWandererUpdateSaltF[((aIndex + 29U)) & S_SALT1]);
            aWandererD = aWandererD + (((RotL64(aPrevious, 3U) + RotL64(aOrbiterA, 11U)) + aOrbiterI) + RotL64(aCarry, 3U));
