            aWandererB = aWandererB ^ ((RotL64(aIngress, 41U) + RotL64(aOrbiterD, 18U)) + aOrbiterA);
            aWandererE = aWandererE + ((RotL64(aScatter, 35U) + RotL64(aOrbiterI, 27U)) + aOrbiterC);
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 24U) + RotL64(aOrbiterB, 3U)) + aOrbiterJ);
            aWandererH = aWandererH + (((RotL64(aIngress, 11U) + RotL64(aOrbiterF, 41U)) + aOrbiterC) + aKeyRotateAWandererUpdateSaltD[((aIndex + 15U)) & S_SALT1]);
