            aOrbiterE = (((aWandererC + RotL64(aCross, 3U)) + RotL64(aCarry, 5U)) + 0x0D2812AD118ED3AFULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 8U)) & S_SALT1];
