            aOrbiterG = (((aWandererG + RotL64(aIngress, 35U)) + RotL64(aCarry, 47U)) + 0x1D14F5B33232CEE3ULL) + aKeyRotateAOrbiterAssignSaltD[((aIndex + 28U)) & S_SALT1];
            aOrbiterD = ((aWandererC + RotL64(aCross, 41U)) + 0x39C73211EE1BD753ULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterH = ((aWandererB + RotL64(aPrevious, 57U)) + RotL64(aCarry, 3U)) + 0x668B2C54B4FD5D01ULL;
