            aOrbiterK = (aOrbiterK + aOrbiterD) + 0xE890371D6272348CULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0xA1DE8A140D7B4613ULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 13U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xB91B2B40E1EA65EBULL), 27U);
