            aOrbiterH = (aOrbiterH + aOrbiterE) + 0x19CDD9CA188E7D1AULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterH) ^ 0x98DE2A1207E3A48EULL;
            aOrbiterI = RotL64((aOrbiterI * 0xD84C838E8750CF55ULL), 57U);
