            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0xC49AC4287E8C3964ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 23U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x940F2EA56E69C1C5ULL), 5U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterH) + 0xCCE19ED7539F2250ULL) + aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 16U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0x2FAEF6ACD0F3D9A5ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x4D7B6AADF27755BBULL), 19U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0xF0D04A9315B978B2ULL) + aKeyRotateAOrbiterUpdateSaltD[((aIndex + 14U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterE) ^ 0x97D1510895A3BA94ULL;
