            aWandererF = aWandererF ^ (((RotL64(aScatter, 35U) + RotL64(aOrbiterD, 35U)) + aOrbiterE) + aKeyRotateAWandererUpdateSaltB[((aIndex + 29U)) & S_SALT1]);
